/**
 * ai-client-utils.js
 * Utility functions for initializing AI clients in MCP context
 */

import { Anthropic } from '@anthropic-ai/sdk';
import OpenAI from 'openai';
import dotenv from 'dotenv';

// Load environment variables for CLI mode
dotenv.config();

// Default model configuration - Updated for OpenRouter
const DEFAULT_MODEL_CONFIG = {
	model: 'anthropic/claude-3.5-sonnet', // Example OpenRouter model ID
	maxTokens: 4000, // Adjusted default
	temperature: 0.7 // Adjusted default
};

/**
 * Get an OpenRouter client instance initialized with MCP session environment variables
 * Uses OpenAI SDK configured for OpenRouter API
 * @param {Object} [session] - Session object from MCP containing environment variables
 * @param {Object} [log] - Logger object to use (defaults to console)
 * @returns {OpenAI} OpenAI client instance configured for OpenRouter
 * @throws {Error} If API key is missing
 */
export function getOpenRouterClientForMCP(session, log = console) {
	try {
		// Extract API key from session.env or fall back to environment variables
		const apiKey = session?.env?.OPENROUTER_API_KEY || process.env.OPENROUTER_API_KEY;

		if (!apiKey) {
			throw new Error(
				'OPENROUTER_API_KEY not found in session environment or process.env'
			);
		}

		// Initialize and return a new OpenAI client for OpenRouter
		return new OpenAI({
			baseURL: 'https://openrouter.ai/api/v1',
			apiKey: apiKey,
			defaultHeaders: {
				'HTTP-Referer': 'https://github.com/erfan/not-only-claude-task-master', // Recommended by OpenRouter
				'X-Title': 'Task Master MCP' // Recommended by OpenRouter
			}
		});
	} catch (error) {
		log.error(`Failed to initialize OpenRouter client: ${error.message}`);
		throw error;
	}
}

/**
 * Get a Perplexity client instance initialized with MCP session environment variables
 * @param {Object} [session] - Session object from MCP containing environment variables
 * @param {Object} [log] - Logger object to use (defaults to console)
 * @returns {OpenAI} OpenAI client configured for Perplexity API
 * @throws {Error} If API key is missing or OpenAI package can't be imported
 */
export async function getPerplexityClientForMCP(session, log = console) {
	try {
		// Extract API key from session.env or fall back to environment variables
		const apiKey =
			session?.env?.PERPLEXITY_API_KEY || process.env.PERPLEXITY_API_KEY;

		if (!apiKey) {
			throw new Error(
				'PERPLEXITY_API_KEY not found in session environment or process.env'
			);
		}

		// Dynamically import OpenAI (it may not be used in all contexts)
		const { default: OpenAI } = await import('openai');

		// Initialize and return a new OpenAI client configured for Perplexity
		return new OpenAI({
			apiKey,
			baseURL: 'https://api.perplexity.ai'
		});
	} catch (error) {
		log.error(`Failed to initialize Perplexity client: ${error.message}`);
		throw error;
	}
}

/**
 * Get model configuration from session environment or fall back to defaults
 * @param {Object} [session] - Session object from MCP containing environment variables
 * @param {Object} [defaults] - Default model configuration to use if not in session
 * @returns {Object} Model configuration with model, maxTokens, and temperature
 */
export function getModelConfig(session, defaults = DEFAULT_MODEL_CONFIG) {
	// Get values from session or fall back to defaults
	return {
		model: session?.env?.MODEL || defaults.model,
		maxTokens: parseInt(session?.env?.MAX_TOKENS || defaults.maxTokens),
		temperature: parseFloat(session?.env?.TEMPERATURE || defaults.temperature)
	};
}

/**
 * Returns the best available AI model based on specified options
 * @param {Object} session - Session object from MCP containing environment variables
 * @param {Object} options - Options for model selection
 * @param {boolean} [options.requiresResearch=false] - Whether the operation requires research capabilities
 * @param {Object} [log] - Logger object to use (defaults to console)
 * @returns {Promise<Object>} Selected model info with type and client
 * @throws {Error} If no AI models are available
 */
export async function getBestAvailableAIModel(
	session,
	options = {},
	log = console
) {
	const { requiresResearch = false } = options;

	// First choice: Perplexity if research is required and API key is available
	if (
		requiresResearch &&
		(session?.env?.PERPLEXITY_API_KEY || process.env.PERPLEXITY_API_KEY)
	) {
		try {
			const client = await getPerplexityClientForMCP(session, log);
			log.info('Using Perplexity client for research task.');
			return { type: 'perplexity', client };
		} catch (error) {
			log.warn(`Perplexity client initialization failed: ${error.message}. Falling back.`);
			// Fall through to OpenRouter as backup
		}
	}

	// Second choice / Default: OpenRouter if API key is available
	if (session?.env?.OPENROUTER_API_KEY || process.env.OPENROUTER_API_KEY) {
		try {
			const client = getOpenRouterClientForMCP(session, log);
			log.info('Using OpenRouter client.');
			return { type: 'openrouter', client };
		} catch (error) {
			log.error(`OpenRouter client initialization failed: ${error.message}`);
			// Fall through to error if no other options
		}
	}

	// Fallback: Perplexity if research wasn't required but OpenRouter failed/missing
	if (session?.env?.PERPLEXITY_API_KEY || process.env.PERPLEXITY_API_KEY) {
		try {
			const client = await getPerplexityClientForMCP(session, log);
			log.warn('OpenRouter not available, falling back to Perplexity (if available).');
			return { type: 'perplexity', client };
		} catch (error) {
			log.warn(`Perplexity client fallback initialization failed: ${error.message}`);
			// Fall through to final error
		}
	}

	// If we got here, no models were successfully initialized
	throw new Error(
		'No AI models available. Please check OPENROUTER_API_KEY and/or PERPLEXITY_API_KEY in session or environment variables.'
	);
}

/**
 * Handle AI API errors with user-friendly messages
 * @param {Error} error - The error from the AI API
 * @returns {string} User-friendly error message
 */
export function handleAIError(error) {
	// Check for OpenRouter/OpenAI specific errors (structure might differ)
	if (error.response && error.response.data && error.response.data.error) {
		const err = error.response.data.error;
		switch (err.type) {
			case 'rate_limit_exceeded': // Example type, check OpenRouter docs
				return 'You have exceeded the rate limit for the selected model or your OpenRouter account. Please check your OpenRouter usage and limits.';
			case 'invalid_request_error':
				return `Invalid request to AI service: ${err.message}. If this persists, please report it as a bug.`;
			case 'authentication_error':
				return `Authentication failed. Please check your OPENROUTER_API_KEY. Details: ${err.message}`;
			case 'insufficient_quota':
				return `You have insufficient quota on OpenRouter. Please check your account balance/limits. Details: ${err.message}`;
			// Add more specific OpenRouter error types if known
			default:
				return `AI API error (${err.type}): ${err.message}`;
		}
	}

	// Check for network/timeout errors
	if (error.message?.toLowerCase().includes('timeout')) {
		return 'The request to the AI service timed out. Please try again.';
	}
	if (error.message?.toLowerCase().includes('network')) {
		return 'There was a network error connecting to the AI service. Please check your internet connection and try again.';
	}

	// Fallback for other errors
	// Avoid logging raw error here as logger might not be available easily
	return `Error communicating with the AI service: ${error.message}`;
}
